const crypto = require('crypto');

const items = $input.all();
const output = [];

for (const item of items) {
  const p = item.json;
  const paraphrases = Array.isArray(p.paraphrases)
    ? p.paraphrases.join(' | ')
    : (typeof p.paraphrases === 'string' ? p.paraphrases : '');

  const conditions = typeof p.conditions === 'object' && p.conditions !== null
    ? JSON.stringify(p.conditions)
    : String(p.conditions || '');

  const validity = `${p.effective_from || ''} - ${p.effective_to ? p.effective_to : 'Süresiz'}`;
  const source = `${p.source_title || 'Sentetik İK Politikası'} / ${p.source_section || 'Genel'} (Sahip: ${p.owner || 'İK'})`;

  const content = `Kategori: ${p.category}
Kanonik Soru: ${p.canonical_question}
Alternatif Sorular: ${paraphrases}
Onaylı Cevap: ${p.answer_text}
Koşullar: ${conditions}
Geçerlilik: ${validity}
Kaynak: ${source}`;

  const contentHash = crypto.createHash('sha256').update(content, 'utf8').digest('hex');
  const tokenCount = Math.ceil(content.split(/\s+/).filter(Boolean).length * 1.3);

  const metadata = {
    policy_code: p.policy_code,
    category: p.category,
    version: p.version,
    effective_from: p.effective_from,
    effective_to: p.effective_to,
    approved: p.approved,
    synthetic: p.synthetic,
    sensitivity: p.sensitivity,
    owner: p.owner,
    source_section: p.source_section
  };

  output.push({
    json: {
      policy_code: p.policy_code,
      title: `${p.category} - ${p.canonical_question}`,
      content,
      content_hash: contentHash,
      token_count: tokenCount,
      metadata,
      metadata_json: JSON.stringify(metadata),
      source_uri: `hr.policy_item/${p.policy_code}`,
      sensitivity: p.sensitivity || 'internal_demo'
    }
  });
}

return output;

const transformedItems = $('Transform & Hash Documents').all();
const embeddingResponses = $input.all();
const records = [];

for (let i = 0; i < transformedItems.length; i++) {
  const t = transformedItems[i].json;
  const e = embeddingResponses[i]?.json;
  const vector = e?.embeddings?.[0];
  if (!vector || !Array.isArray(vector) || vector.length !== 1024) {
    throw new Error(`Embedding generation failed or dimension mismatch for ${t.policy_code}`);
  }
  records.push({
    policy_code: t.policy_code,
    title: t.title,
    content: t.content,
    content_hash: t.content_hash,
    token_count: t.token_count,
    metadata: t.metadata,
    source_uri: t.source_uri,
    sensitivity: t.sensitivity,
    embedding_vector: `[${vector.join(',')}]`
  });
}

return [{
  json: {
    total_processed: records.length,
    records_payload: JSON.stringify(records)
  }
}];
